from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.models import Payment
from ledgerly.payments import capture_partial
from ledgerly.errors import BillingError

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def p(status="authorized", amt="100.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0)

for amt in ["0","-1","100.01"]:
    try: capture_partial(p(), amt, T0); print("FAIL", amt)
    except BillingError as e: print("ok reject", amt, e.code)
try: capture_partial(p("captured"), "10", T0); print("FAIL state")
except BillingError as e: print("ok reject state", e.code)

x=p(); r=capture_partial(x,"60.005",T0); print("round", r.amount, r.status, r.captured_at)
# idempotency
y=p(); r1=capture_partial(y,"50",T0,idempotency_key="k1")
r2=capture_partial(y,"10",T0,idempotency_key="k1")
print("same record", r1 is r2, r2.amount, len(audit.events("payment_captured")))
print(audit.events("payment_captured")[-1])
EOF"}

